begin;
select plan(23);
insert into public.bookmarks(id,url,url_key,title) values ('bbbbbbbb-9800-4000-8000-000000000001','https://example.com/worker','https://example.com/worker','Worker');
insert into public.bookmark_jobs(id,kind,state,lease_token,lease_expires_at,total) values ('aaaaaaaa-9800-4000-8000-000000000001','check','processing','cccccccc-9800-4000-8000-000000000001',now()+interval '90 seconds',1);
insert into public.bookmark_job_items(job_id,bookmark_id,expected_version) values ('aaaaaaaa-9800-4000-8000-000000000001','bbbbbbbb-9800-4000-8000-000000000001',1);
select ok((public.bookmark_health_host_claim('example.com')->>'token') is not null,'first host permit granted');
select ok((public.bookmark_health_host_claim('example.com')->>'token') is null,'same host permit excludes second request');
select is(public.bookmark_health_host_release('example.com','cccccccc-9800-4000-8000-000000000001',null),false,'foreign permit cannot release');
update private.bookmark_health_hosts set lease_expires_at=now()-interval '1 second';
select ok((public.bookmark_health_host_claim('example.com')->>'token') is not null,'expired host permit recovers');
select is(public.bookmark_health_ai_reserve('aaaaaaaa-9800-4000-8000-000000000001','cccccccc-9800-4000-8000-000000000001','bbbbbbbb-9800-4000-8000-000000000001','eeeeeeee-9800-4000-8000-000000000001',repeat('a',64))->>'state','reserved','AI reservation guarded by existing budget');
select is((select health_bookmark_id from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000001'),'bbbbbbbb-9800-4000-8000-000000000001'::uuid,'reservation linked to item');
select is(public.bookmark_health_ai_settle('eeeeeeee-9800-4000-8000-000000000001','{"state":"settled","chargedNano":42000,"inputTokens":100,"outputTokens":20,"decision":{"choice":"present","basis":"content_match","confidence":1}}'),true,'known receipt settles');
select is(public.bookmark_health_ai_settle('eeeeeeee-9800-4000-8000-000000000001','{"state":"settled","chargedNano":42000}'),true,'receipt settlement idempotent');
select is(public.bookmark_health_ai_reserve('aaaaaaaa-9800-4000-8000-000000000001','cccccccc-9800-4000-8000-000000000001','bbbbbbbb-9800-4000-8000-000000000001','eeeeeeee-9800-4000-8000-000000000002',repeat('a',64))->>'state','cached','same evidence uses settled decision');
update public.bookmark_jobs set lease_expires_at=now()-interval '1 second' where id='aaaaaaaa-9800-4000-8000-000000000001';
select is(public.bookmark_worker_commit('aaaaaaaa-9800-4000-8000-000000000001','cccccccc-9800-4000-8000-000000000001','{"items":[]}'),false,'expired commit rejected independently of receipt');
select is((select charged_nano from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000001'),42000::bigint,'late/stale commit does not remove known cost');
select is(has_function_privilege('authenticated','public.bookmark_health_ai_settle(uuid,jsonb)','EXECUTE'),false,'owner cannot forge worker receipts');

update public.bookmark_jobs set state='paused' where id<>'aaaaaaaa-9800-4000-8000-000000000001';
update public.bookmark_jobs set state='processing',lease_expires_at=now()+interval '90 seconds' where id='aaaaaaaa-9800-4000-8000-000000000001';
select is(public.bookmark_health_ai_reserve('aaaaaaaa-9800-4000-8000-000000000001','cccccccc-9800-4000-8000-000000000001','bbbbbbbb-9800-4000-8000-000000000001','eeeeeeee-9800-4000-8000-000000000003',repeat('b',64))->>'state','reserved','second evidence can reserve independently');
update public.bookmark_jobs set lease_expires_at=now()-interval '1 second' where id='aaaaaaaa-9800-4000-8000-000000000001';
select is(public.bookmark_worker_commit('aaaaaaaa-9800-4000-8000-000000000001','cccccccc-9800-4000-8000-000000000001','{"receipt":{"reservationId":"eeeeeeee-9800-4000-8000-000000000003","result":{"state":"settled","chargedNano":90000}},"items":[]}'),false,'late receipt cannot apply stale observation');
select is((select charged_nano from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000003'),90000::bigint,'late known receipt survives expired publication lease');
insert into public.bookmarks(id,url,url_key,title) values ('bbbbbbbb-9800-4000-8000-000000000002','https://example.com/next','https://example.com/next','Next');
insert into public.bookmark_job_items(job_id,bookmark_id,expected_version) values ('aaaaaaaa-9800-4000-8000-000000000001','bbbbbbbb-9800-4000-8000-000000000002',1);
update public.bookmark_job_items set state='waiting',available_at=now()+interval '1 month',work='{"phase":"decision"}' where bookmark_id='bbbbbbbb-9800-4000-8000-000000000001';
update public.bookmark_jobs set state='retry',available_at=now() where id='aaaaaaaa-9800-4000-8000-000000000001';
select is(public.bookmark_worker_claim()->'items'->0->>'id','bbbbbbbb-9800-4000-8000-000000000002','future budget wait leaves the next page claim available');
update public.bookmark_job_items set state='pending',available_at=now(),work='{"phase":"decision","reservationId":"eeeeeeee-9800-4000-8000-000000000004"}' where bookmark_id='bbbbbbbb-9800-4000-8000-000000000001';
insert into public.bookmark_ai_reservations(id,job_id,month,reserved_nano,input_tokens,health_evidence_key,health_bookmark_id) values('eeeeeeee-9800-4000-8000-000000000004','aaaaaaaa-9800-4000-8000-000000000001',date_trunc('month',now() at time zone 'Asia/Seoul')::date,2752512,65536,repeat('c',64),'bbbbbbbb-9800-4000-8000-000000000001');
update public.bookmark_jobs set lease_expires_at=now()-interval '1 second' where id='aaaaaaaa-9800-4000-8000-000000000001';
select is(public.bookmark_worker_claim()->'items'->0->>'id','bbbbbbbb-9800-4000-8000-000000000002','crashed AI request does not block independent page item');
select is((select state from public.bookmark_job_items where bookmark_id='bbbbbbbb-9800-4000-8000-000000000001'),'failed','uncertain request fails only its own item');
select is((select state from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000004'),'uncertain','crash preserves ambiguous reservation');
select ok(public.bookmark_health_ai_settle('eeeeeeee-9800-4000-8000-000000000004','{"state":"settled","chargedNano":3000000,"decision":{"choice":"present"}}'),'overrun receipt is recorded');
select is((select charged_nano from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000004'),3000000::bigint,'overrun keeps actual charge');
select is((select state from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000004'),'uncertain','overrun blocks further AI budget use');
select is((select health_decision from public.bookmark_ai_reservations where id='eeeeeeee-9800-4000-8000-000000000004'),null::jsonb,'overrun cannot cache a decision');
select * from finish(); rollback;
